={{ JSON.stringify({ "systemInstruction": { "parts": [{ "text": "You are a strict JSON extractor and classifier for Davya consultancy's finance system. Output ONLY JSON matching the provided schema. Every message is exactly one type: "capture", "question", or "ignore".

TYPE = "capture": user is LOGGING a finance event. MUST include: type, category, amount (integer, in rupees). MUST NOT include: question_text, intent, time_range, filter.
- "got 50k from priya 9999911111, ref nisha" => {"type":"capture","category":"Payment","amount":50000,"student_phone":"9999911111","student_name":"priya","referrer_name":"nisha"}
- "priya paid 20k more, pending 30k" => {"type":"capture","category":"Payment","amount":20000,"student_name":"priya","is_partial":true}
- "paid 5k for fb ads" => {"type":"capture","category":"Expense","amount":5000,"expense_category":"Marketing","notes":"fb ads"}
- "bought 100k tata motors" => {"type":"capture","category":"Investment","amount":100000,"asset_name":"Tata Motors","investment_direction":"out"}
- "tata motors paid 120k" => {"type":"capture","category":"Investment","amount":120000,"asset_name":"Tata Motors","investment_direction":"in"}

TYPE = "question": user is LOOKING UP past records. MUST include: type, question_text, intent. MUST NOT include: category, amount, student_phone, asset_name, expense_category, investment_direction, is_partial. Set time_range to null — Laravel parses dates from question_text. filter is optional.
- "what did i spend on fb ads this month" => {"type":"question","question_text":"what did i spend on fb ads this month","intent":"spend_by_category","time_range":null,"filter":{"category":"Marketing"} }
- "show payments from priya" => {"type":"question","question_text":"show payments from priya","intent":"payments_by_student","time_range":null,"filter":{"student_name":"priya"} }
- "what is Nikhil ledger balance" => {"type":"question","question_text":"what is Nikhil ledger balance","intent":"ledger_balance","time_range":null,"filter":{"owner_name":"Nikhil"} }

TYPE = "ignore": unrelated to finance (greetings, team chatter, off-topic). MUST include only: type, reason.
- "@team lunch at 2?" => {"type":"ignore","reason":"team chatter"}
- "lol" => {"type":"ignore","reason":"chatter"}

Rules:
- For capture, NEVER omit amount. If amount is not stated, type is NOT capture — use ignore.
- Questions have past-tense or interrogative cues ("what", "show", "how much", "balance"). Captures have imperative/report cues ("got", "paid", "bought").
- If unsure between capture and question, choose ignore.
- Never fabricate fields. Omit unknown optional fields.
- Never reply conversationally. JSON only." }] }, "contents": [{ "role": "user", "parts": [{ "text": (($json.text || $json.event?.text || '').replace(/<(?:[^|>]+\|)?([^>]+)>/g, '$1')) }] }], "generationConfig": { "temperature": 0.1, "responseMimeType": "application/json", "responseSchema": { "type": "object", "properties": { "type": { "type": "string", "enum": ["capture", "question", "ignore"] }, "category": { "type": "string", "enum": ["Payment", "Expense", "Investment"] }, "amount": { "type": "number" }, "student_phone": { "type": "string" }, "student_name": { "type": "string" }, "referrer_name": { "type": "string" }, "is_partial": { "type": "boolean" }, "expense_category": { "type": "string" }, "asset_name": { "type": "string" }, "investment_direction": { "type": "string", "enum": ["in", "out"] }, "notes": { "type": "string" }, "question_text": { "type": "string" }, "intent": { "type": "string", "enum": ["payments_by_student", "spend_by_category", "ledger_balance", "recent_captures", "totals_by_range", "student_status", "freeform"] }, "time_range": { "type": "object", "properties": { "from": { "type": "string" }, "to": { "type": "string" } } }, "filter": { "type": "object" }, "reason": { "type": "string" } }, "required": ["type"] } } }) }}

parameters.jsCode:
// Dispatch by type — capture / question / ignore (v2 assistant + amount fallback)
const triggerData = $('Slack Trigger — new message').item.json;

// Bot-loop guard
if (triggerData.bot_id || triggerData.subtype === 'bot_message' || triggerData.app_id) {
  return null;
}

const slackChannel = triggerData.channel || triggerData.event?.channel || '';
const slackTs      = triggerData.ts || triggerData.event?.ts || '';
const slackUser    = triggerData.user || triggerData.event?.user || '';
const rawInput     = (triggerData.text || triggerData.event?.text || '').slice(0, 4000);

// Parse Gemini response
let gemini = null;
let parseError = null;
try {
  const geminiRaw = $input.item.json.body?.candidates?.[0]?.content?.parts?.[0]?.text;
  if (geminiRaw) gemini = JSON.parse(geminiRaw);
  else parseError = 'no candidates in Gemini response';
} catch (e) {
  parseError = 'JSON parse error: ' + e.message;
}

if (!gemini || !gemini.type) {
  return { json: { target: 'failed', payload: { slack_message_id: slackTs, slack_channel: slackChannel, raw_input: rawInput, error_reason: parseError || 'gemini missing type' }, slack_ts: slackTs, slack_channel: slackChannel, slack_user: slackUser, gemini } };
}

// type = ignore
if (gemini.type === 'ignore') return null;

// type = question
if (gemini.type === 'question') {
  // Gemini often returns non-ISO strings in time_range ("this week"). Laravel requires
  // real ISO dates, so drop the whole object unless both from+to look like YYYY-MM-DD.
  let timeRange = null;
  const tr = gemini.time_range;
  const isIso = (v) => typeof v === 'string' && /^\d{4}-\d{2}-\d{2}/.test(v);
  if (tr && typeof tr === 'object' && isIso(tr.from) && isIso(tr.to)) {
    timeRange = { from: tr.from, to: tr.to };
  }
  // Drop non-plain-object filter too (defensive — Laravel validates)
  let filter = null;
  if (gemini.filter && typeof gemini.filter === 'object' && !Array.isArray(gemini.filter)) {
    filter = gemini.filter;
  }
  // Intent + filter fallbacks — Gemini 2.5 Flash often drops these fields for questions.
  let intent = gemini.intent || null;
  if (!intent || intent === 'freeform') {
    // ledger_balance: "what is X ledger balance" / "X's balance" / "balance for X"
    let m = rawInput.match(/\b(?:what(?:'s|\s+is)|show|tell\s+me)\s+(?:the\s+)?(\w+)(?:'s)?\s+(?:ledger\s+)?balance\b/i)
         || rawInput.match(/\b(?:ledger\s+)?balance\s+(?:for|of)\s+(\w+)\b/i);
    if (m) {
      intent = 'ledger_balance';
      filter = filter || { owner_name: m[1].trim() };
    }
    // spend_by_category: "what did i spend on X" / "how much on X"
    if (!intent || intent === 'freeform') {
      m = rawInput.match(/\b(?:what\s+did\s+(?:i|we)|how\s+much(?:\s+did\s+(?:i|we))?)\s+spen[dt]\s+(?:on|for)\s+(.+?)(?:\s+(?:this|last|in|during)\s+\w+)?[\s.?!]*$/i);
      if (m) {
        intent = 'spend_by_category';
        filter = filter || { category: m[1].trim() };
      }
    }
  }
  if (!intent) intent = 'freeform';
  return {
    json: {
      target: 'assistant',
      payload: {
        slack_message_id: slackTs,
        slack_channel:    slackChannel,
        slack_user_id:    slackUser,
        question_text:    gemini.question_text || rawInput,
        intent:           intent,
        time_range:       timeRange,
        filter:           filter,
      },
      slack_ts: slackTs, slack_channel: slackChannel, slack_user: slackUser, gemini,
    }
  };
}

// type = capture — amount regex fallback before bailing
if (gemini.type === 'capture' && typeof gemini.amount !== 'number') {
  // Strip phone-like 10-digit runs (so they don't match as amounts)
  const scrubbed = rawInput.replace(/\b\d{10,}\b/g, ' ');
  const crMatch = scrubbed.match(/\b(\d+(?:\.\d+)?)\s*cr\b/i);
  const lMatch  = scrubbed.match(/\b(\d+(?:\.\d+)?)\s*(?:l|lakh|lac)\b/i);
  const kMatch  = scrubbed.match(/\b(\d+(?:\.\d+)?)\s*k\b/i);
  const plain   = scrubbed.match(/\b(\d{2,})\b/);
  if (crMatch)      gemini.amount = Math.round(parseFloat(crMatch[1]) * 10000000);
  else if (lMatch)  gemini.amount = Math.round(parseFloat(lMatch[1]) * 100000);
  else if (kMatch)  gemini.amount = Math.round(parseFloat(kMatch[1]) * 1000);
  else if (plain)   gemini.amount = parseInt(plain[1], 10);
}

if (gemini.type !== 'capture' || !gemini.category || typeof gemini.amount !== 'number') {
  return { json: { target: 'failed', payload: { slack_message_id: slackTs, slack_channel: slackChannel, raw_input: rawInput, error_reason: parseError || 'capture missing required fields (after regex fallback)' }, slack_ts: slackTs, slack_channel: slackChannel, slack_user: slackUser, gemini } };
}

const category = gemini.category;
let target; let payload;

if (category === 'Payment') {
  target = 'payments';
  payload = { slack_message_id: slackTs, raw_input: rawInput };
  if (gemini.amount !== undefined)        payload.amount = gemini.amount;
  if (gemini.student_phone !== undefined) payload.student_phone = gemini.student_phone;
  if (gemini.student_name !== undefined)  payload.student_name = gemini.student_name;
  if (gemini.referrer_name !== undefined) payload.referrer_name = gemini.referrer_name;
  if (gemini.is_partial !== undefined)    payload.is_partial = gemini.is_partial;
  if (!payload.referrer_name) {
    const m = rawInput.match(/\bref(?:erred\s+by)?[:\s]\s*([A-Za-z][A-Za-z\s'.-]*?)(?:[,.!?]|$)/i);
    if (m) {
      payload.referrer_name = m[1].trim();
      gemini.referrer_name = payload.referrer_name;
    }
  }
} else if (category === 'Expense') {
  target = 'expenses';
  payload = { amount: gemini.amount, category: gemini.expense_category || null, description: gemini.notes || null, slack_message_id: slackTs, raw_input: rawInput };
} else if (category === 'Investment') {
  target = 'investments';
  payload = { asset_name: gemini.asset_name || null, amount: gemini.amount, direction: (gemini.investment_direction || '').toLowerCase() || null, slack_message_id: slackTs, raw_input: rawInput };
  // Fallback A: Gemini 2.5 Flash sometimes misplaces the asset into student_name. Salvage.
  if (!payload.asset_name && gemini.student_name) {
    payload.asset_name = gemini.student_name;
    gemini.asset_name = payload.asset_name;
  }
  // Fallback B: regex against raw input — "bought/sold/purchased/invested [amt] <asset>".
  if (!payload.asset_name) {
    const m = rawInput.match(/\b(?:bought|sold|purchased|invested(?:\s+in)?|redeemed|put\s+in)\s+(?:\d+(?:\.\d+)?\s*(?:cr|l|lakh|lac|k)\s+)?([A-Za-z][A-Za-z0-9\s.&'-]*?)(?:\s+(?:for|at|via|@|ref|on)\b|[,.!?]|$)/i);
    if (m) {
      payload.asset_name = m[1].trim();
      gemini.asset_name = payload.asset_name;
    }
  }
  // Direction default: "bought/purchased/invested/put in" => out; "sold/redeemed" => in.
  if (!payload.direction) {
    if (/\b(?:bought|purchased|invested(?:\s+in)?|put\s+in)\b/i.test(rawInput))      payload.direction = 'out';
    else if (/\b(?:sold|redeemed)\b/i.test(rawInput))                                 payload.direction = 'in';
    if (payload.direction) gemini.investment_direction = payload.direction;
  }
}

return { json: { target, payload, slack_ts: slackTs, slack_channel: slackChannel, slack_user: slackUser, gemini } };

