// Pre-Gemini bot-loop guard — skip bot-sourced messages BEFORE calling Gemini
// (Dispatch still has the same check for belt+suspenders; this one saves the API call.)
const t = $input.item.json;
if (t.bot_id || t.subtype === 'bot_message' || t.app_id) {
  return null;
}
return { json: t };

// Attach Slack file permalink as proof_url on the payment payload.
const dispatch = $('Dispatch by category').item.json;
const files = $('Slack Trigger — new message').item.json.files || [];
const firstImage = files.find(f => (f.mimetype || '').startsWith('image/'));
if (firstImage) {
  dispatch.payload = dispatch.payload || {};
  dispatch.payload.proof_url = firstImage.permalink;
}
return { json: dispatch };
